doc='# Kabita Live · Forty-seven stories of home\n\nମାଟିର ମହକ · ମନର ସ୍ୱର\n\nOriginal cover narratives for proposed new artwork. Pairings use the archive’s verified issue dates; they do not describe historical issue contents. Cultural notes are distinct from imagined stories. Generated art is interpretation, not documentary evidence.\n\n'
for p in catalogue:
 doc+=f"## Issue {p['number']} · {p['date']} — {p['title']}\n\n**{p['theme']}**\n\n{p['story']}\n\nCultural connection: {p['cultural_connection']}\n\n"
 for s in p['sources']:doc+=f"Reference: [{s['label']}]({s['url']})\n\n"
